1143:   async #collectCatalogs(): Promise<AgentSessionSummary[]> {
1144:     const sessions: AgentSessionSummary[] = [];
1145:     for (const backend of this.#backends) {
1146:       if (!backend.isReady()) continue;
1147:       try {
1148:         const started = Date.now();
1149:         const [active, archived] = await Promise.all([backend.catalog(), backend.catalog(true)]);
1150:         const catalog = [...new Map([...active, ...archived].map((entry) => [entry.sessionId, entry])).values()];
1151:         this.#options.log?.(`[debug] session.list：${backend.kind} 返回 ${catalog.length} 条（${Date.now() - started}ms）`);
1152:         sessions.push(...catalog);
1153:       } catch (error) {
1154:         this.#options.log?.(`拉取 ${backend.kind} 会话目录失败，本次跳过该后端：${describeError(error)}`);
1155:       }
1156:     }
1157:     const desktopIds = this.#desktopOwnedIds;
1158:     return sessions.filter(entry => entry.agentKind !== "codex" || !desktopIds.has(entry.sessionId)).slice(0, 2_000);
1159:   }
