29: void DiagnosticLogModel::flush() {
30:     if (m_pending.isEmpty()) return;
31:     const int removed = qMax(0, int(m_lines.size() + m_pending.size()) - MaxEntries);
32:     if (removed > 0) {
33:         beginRemoveRows({}, 0, removed - 1);
34:         m_lines.remove(0, removed);
35:         endRemoveRows();
36:     }
37:     const int first = m_lines.size();
38:     beginInsertRows({}, first, first + int(m_pending.size()) - 1);
39:     m_lines.append(m_pending);
40:     m_pending.clear();
41:     endInsertRows();
42: }

