42: export function parseAgentVersion(value: string): { core: bigint[]; pre: string[] } | undefined {
43:   const match = versionPattern.exec(value.trim());
44:   if (!match || match[4]?.split(".").some(part => /^\d+$/.test(part) && part.length > 1 && part.startsWith("0"))) return undefined;
45:   return { core: [BigInt(match[1]!), BigInt(match[2]!), BigInt(match[3]!)], pre: match[4]?.split(".") ?? [] };
46: }
47: export function compareAgentVersions(left: string, right: string): number | undefined {
48:   const a = parseAgentVersion(left); const b = parseAgentVersion(right);
49:   if (!a || !b) return undefined;
50:   for (let i = 0; i < 3; i += 1) if (a.core[i] !== b.core[i]) return a.core[i]! > b.core[i]! ? 1 : -1;

