591: /**
592:  * A source-versioned live-state transition. It is deliberately self-contained: a client may
593:  * apply it only when `baseSeq` is its current source sequence, otherwise it must recover from a
594:  * checkpoint instead of guessing a missing delta.
595:  */
596: export const SessionPatchSchema = z.strictObject({
597:   type: z.literal("session.patch"),
598:   sessionId: z.string().min(1).max(256),
599:   source: SessionSourceEpochSchema,
600:   baseSeq: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER),
601:   seq: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
602:   checkpointId: z.string().min(1).max(256),
603:   head: SessionBranchCursorSchema,
604:   headCompleteness: z.enum(["complete", "unknown"]),
605:   live: SessionLiveStateSchema,
606:   /** Immutable nodes committed by this transition; ingest before switching head/live. */
607:   entries: z.array(RemoteSessionEntrySchema).max(256).optional(),
608: }).refine(patch => patch.source.seq === patch.seq && patch.baseSeq < patch.seq, {
609:   message: "Source patch must advance from baseSeq to the matching source sequence",
610: });
611: export type SessionPatch = z.infer<typeof SessionPatchSchema>;
