6: type Record = { item: ActiveNotification; transient: boolean; deviceId?: string };
7: type Projection = { sessionId: string | null; epoch?: string; active: boolean; sourceRevision: number; revision: number;
8:   verification: "confirmed" | "unknown"; complete: boolean; records: Map<string, Record>; dismissed: Map<string, Set<string>>;
9:   outcomeReceipts: Set<string>; removedIds: Set<string> };
10: 
11: /** Current-state middleware. Native meaning belongs to producers; no message matching here. */
12: export class NotificationStore {
13:   readonly hostEpoch = randomUUID();
14:   readonly #runtimes = new Map<string, Projection>();
15:   #revision = 0;
16:   readonly #timer: ReturnType<typeof setInterval>;
17:   constructor(readonly changed: (runtimeId: string) => void, readonly now = Date.now) {
18:     this.#timer = setInterval(() => this.expire(), 1000); this.#timer.unref();
19:   }
20:   #get(runtimeId: string): Projection | undefined {
21:     let state = this.#runtimes.get(runtimeId);
22:     if (state === undefined) {
23:       if (this.#runtimes.size >= 2048) {
24:         const retired = [...this.#runtimes].find(([, projection]) => !projection.active);
25:         if (retired === undefined) return undefined;
26:         this.#runtimes.delete(retired[0]);
27:       }
28:       state = { sessionId: null, active: true, sourceRevision: -1, revision: 0, verification: "unknown", complete: false,
29:         records: new Map(), dismissed: new Map(), outcomeReceipts: new Set(), removedIds: new Set() }; this.#runtimes.set(runtimeId, state);
30:     }

